package ai.interviewiq.api.controller; import ai.interviewiq.api.dto.AuthDtos.*; import ai.interviewiq.api.service.AuthService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users/me") public class UserController {final AuthService s;public UserController(AuthService a){s=a;}@GetMapping public UserResponse me(Authentication a){return s.me((Long)a.getPrincipal());}@PatchMapping public UserResponse update(Authentication a,@Valid @RequestBody ProfilePatch patch){return s.update((Long)a.getPrincipal(),patch.displayName());}}
